require 'cgi'
require 'fileutils'
require 'rexml/document'
DIR=File.expand_path(File.dirname(__FILE__))
TEMPLATE=File.expand_path('../../Margo-conteudos-pre-lancamento-atualizado.docx',__dir__)
def e(s);CGI.escapeHTML(s.to_s);end
def ptext(s,style=nil)
  "<w:p><w:pPr>#{style ? "<w:pStyle w:val=\"#{style}\"/><w:keepNext/>" : ''}<w:spacing w:after=\"110\" w:line=\"270\" w:lineRule=\"auto\"/></w:pPr><w:r>#{style ? '' : '<w:rPr><w:sz w:val="21"/></w:rPr>'}<w:t xml:space=\"preserve\">#{e(s)}</w:t></w:r></w:p>"
end
def build(name,title,pages)
  xml='';htmlpages=[]
  pages.each_with_index do |blocks,i|
    xml+='<w:p><w:r><w:br w:type="page"/></w:r></w:p>' if i>0
    h=''
    blocks.each do |type,content|
      case type
      when :tag
        xml+=ptext(content,'Heading3');h+="<div class=\"tag\">#{e(content)}</div>"
      when :title
        xml+=ptext(content,'Title');h+="<h1>#{e(content)}</h1>"
      when :h
        xml+=ptext(content,'Heading2');h+="<h2>#{e(content)}</h2>"
      when :p
        xml+=ptext(content);h+="<p>#{e(content)}</p>"
      when :list
        xml+=content.map{|s|ptext("☐  #{s}")}.join
        h+='<ul class="check">'+content.map{|s|"<li>#{e(s)}</li>"}.join+'</ul>'
      when :table
        xml+='<w:tbl><w:tblPr><w:tblW w:w="9638" w:type="dxa"/><w:tblCellMar><w:top w:w="100" w:type="dxa"/><w:left w:w="100" w:type="dxa"/><w:bottom w:w="100" w:type="dxa"/></w:tblCellMar></w:tblPr>'
        h+='<table>'
        content.each_with_index do |row,n|
          xml+='<w:tr><w:trPr><w:cantSplit/></w:trPr>';h+='<tr>'
          row.each do |cell|
            xml+="<w:tc><w:tcPr><w:shd w:fill=\"#{n==0 ? 'F6DDE9' : 'FFFFFF'}\"/></w:tcPr>#{ptext(cell)}</w:tc>"
            h+="<#{n==0 ? 'th' : 'td'}>#{e(cell)}</#{n==0 ? 'th' : 'td'}>"
          end
          xml+='</w:tr>';h+='</tr>'
        end
        xml+='</w:tbl>'+ptext('');h+='</table>'
      end
    end
    htmlpages<<"<section class=\"page\"><main>#{h}</main><footer>Margô · #{e(title)} &nbsp; #{i+1}</footer></section>"
  end
  css='@page{size:A4;margin:0}*{box-sizing:border-box}body{background:#e9e5e5;margin:0;color:#21171c;font:10.5pt/1.4 Arial,sans-serif}.page{position:relative;background:white;width:210mm;height:297mm;padding:19mm 20mm;margin:14px auto;break-after:page}.page:last-child{break-after:auto}h1{font:26pt/1.1 Georgia,serif;margin:9px 0 16px}h2{font:15pt Georgia,serif;color:#6b1738;margin:18px 0 9px}p{margin:0 0 10px}.tag{color:#ed5f67;font-weight:bold;font-size:9pt;text-transform:uppercase;letter-spacing:1px}.check{list-style:none;padding:0;margin:6px 0 13px}.check li{position:relative;padding-left:19px;margin-bottom:7px}.check li:before{content:"□";position:absolute;left:0;color:#6b1738}table{width:100%;border-collapse:collapse;font-size:9.5pt;line-height:1.35;margin:10px 0}th{text-align:left;background:#6b1738;color:white}td,th{padding:9px 8px;vertical-align:top}tr:nth-child(even){background:#f8eef2}footer{position:absolute;bottom:11mm;right:20mm;color:#6e5d65;font-size:8pt}@media print{body{background:white}.page{margin:0}}'
  html='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>'+e(title)+'</title><style>'+css+'</style>'+htmlpages.join+'<script>document.querySelectorAll(".page").forEach((p,i)=>{const m=p.querySelector("main"),f=p.querySelector("footer");p.dataset.fit=m.getBoundingClientRect().bottom<f.getBoundingClientRect().top?"ok":"overflow"});if(location.hash){const i=Number(location.hash.slice(1));document.querySelectorAll(".page").forEach((p,n)=>{if(n!==i-1)p.remove()})}</script></html>'
  File.write(File.join(DIR,name+'.html'),html)
  stage=File.join(DIR,'.build-'+name);FileUtils.mkdir_p(stage)
  system('unzip','-q','-o',TEMPLATE,'-d',stage) or raise 'template'
  path=File.join(stage,'word/document.xml');source=File.read(path);sect=source[/<w:sectPr\b.*?<\/w:sectPr>/m]
  source=source.sub(/<w:body>.*<\/w:body>/m,"<w:body>#{xml}#{sect}</w:body>");REXML::Document.new(source);File.write(path,source)
  f=File.join(stage,'word/footer1.xml');File.write(f,File.read(f).gsub('Conteúdos de pré-lançamento',e(title)))
  f=File.join(stage,'docProps/core.xml');File.write(f,File.read(f).sub(/<dc:title>.*?<\/dc:title>/m,"<dc:title>#{e(title)}</dc:title>"))
  f=File.join(stage,'docProps/app.xml');File.write(f,File.read(f).gsub(/<Pages>\d+<\/Pages>/,"<Pages>#{pages.size}</Pages>"))
  out=File.join(DIR,name+'.docx');FileUtils.rm_f(out);Dir.chdir(stage){system('zip','-q','-r',out,'.') or raise 'zip'};FileUtils.rm_rf(stage)
  puts "#{name}: #{pages.size} páginas"
end
calendar=[
  [[:tag,'Planejamento para aprovação · versão 03 · 16/10/2026'],[:title,'Calendário de conteúdo'],[:p,'17 a 31 de outubro de 2026 · 3 posts por semana'],[:h,'O que queremos despertar'],[:p,'Vontade de conhecer a casa, sentar à mesa e voltar. As publicações alternam ambiente, acolhimento, pessoas e comida, mostrando a experiência da Margô no dia a dia. Este é um período de testes, sem priorização de dias ou produtos por desempenho.'],[:h,'Datas propostas'],[:table,[['Data','Formato','Pauta'],['17/10 · sáb','Reel','Depoimentos + conversa da Margô — já em edição'],['20/10 · ter','Carrossel','A mesinha da janela'],['22/10 · qui','Carrossel','Os favoritos da Bruna'],['24/10 · sáb','Reel','Uma manhã de domingo na Margô'],['27/10 · ter','Reel','O café começa numa conversa'],['29/10 · qui','Carrossel','Os favoritos do Marcos'],['31/10 · sáb','Carrossel','Uma casa, diferentes jeitos de ficar']]],[:h,'Continuidade da série'],[:p,'05/11 · quinta-feira · Os favoritos da Suelen. Data sugerida para completar os três episódios com intervalo de uma semana. É uma proposta para novembro, dentro da cadência habitual; o restante desse mês ainda será planejado.'],[:p,'A ordem Bruna → Marcos → Suelen é uma sugestão e pode mudar conforme as escolhas e o material captado. Não inclui copies nem legendas nesta etapa.']],
  [[:tag,'Outubro · ideias para avaliar'],[:title,'O que vamos mostrar'],[:h,'20/10 · A mesinha da janela'],[:p,'Carrossel com a vista, a mesinha montada e a sensação de fazer uma pausa ali. A personagem Margô pode aparecer sentada em uma das fotos, como anfitriã. Parte da sugestão enviada pela Bruna.'],[:h,'22/10 · Os favoritos da Bruna'],[:p,'Primeiro episódio de uma série de escolhas pessoais. A Bruna apresenta dois ou três itens do cardápio, explica o que gosta neles e mostra os detalhes que fazem diferença. O objetivo é conhecer a comida pelo olhar de quem vive a casa.'],[:h,'24/10 · Uma manhã de domingo na Margô'],[:p,'Reel com chegada, luz da manhã, atendimento, pedido à mesa e um momento de permanência. Um convite visual para visitar no domingo seguinte.'],[:h,'27/10 · O café começa numa conversa'],[:p,'Reel mostrando como a equipe ajuda alguém que chega sem saber qual café escolher. Troca espontânea, preparo e serviço; uma cafeteria de cafés especiais em que a pessoa se sente à vontade para perguntar.'],[:h,'29/10 · Os favoritos do Marcos'],[:p,'Segundo episódio da série: as escolhas e os motivos do Marcos. A mesma linguagem visual dá unidade, enquanto as preferências e histórias dele tornam o conteúdo diferente do primeiro.'],[:h,'31/10 · Uma casa, diferentes jeitos de ficar'],[:p,'Carrossel fotográfico com encontros, uma pausa individual, pedidos compartilhando a mesa e detalhes do ambiente. Mostrar a casa sendo vivida e diferentes motivos para voltar.'],[:p,'O vídeo de 17/10 segue como já está em produção. Os próximos posts passam a falar da experiência cotidiana da operação.']],
  [[:tag,'Série de favoritos · decisões para aprovação'],[:title,'Pessoas que indicam, pratos que convidam'],[:h,'Como serão os três carrosséis'],[:p,'Um episódio para Bruna, um para Marcos e um para Suelen. Proposta de 6 a 8 imagens por episódio: retrato com o pedido; apresentação visual dos itens; detalhes de textura e preparo; combinação completa à mesa e a pessoa aproveitando sua escolha. A quantidade final depende dos favoritos e das fotos.'],[:p,'Cada pessoa escolhe 2 ou 3 itens, podendo combinar comida e bebida. Uma preferência pessoal e uma razão concreta por item serão a base dos textos, escritos depois da captação. Não é necessário decorar falas nem escolher produtos diferentes só para variar.'],[:h,'O que muda em relação ao calendário anterior'],[:p,'Os favoritos entram em 22 e 29/10 no lugar do Reel sensorial da focaccia e do bastidor da cozinha. Os detalhes de comida e preparo passam a enriquecer os carrosséis. As duas ideias anteriores ficam como reserva para uma próxima etapa.'],[:h,'Alinhamentos antes de fotografar'],[:list,['Aprovar as pautas e as datas, incluindo Suelen em 05/11 e a ordem dos participantes.','Cada participante escolher 2 ou 3 itens e contar por que gosta de cada um.','Combinar com a cozinha a disponibilidade, o preparo e as porções que serão usadas nas fotos.','Confirmar quem participa da cena sobre escolha do café e das fotos de experiência.']],[:p,'Presença confirmada pela Giovanna: Bruna, Marcos e Suelen estarão na casa no domingo, 18/10. As preferências ainda serão levantadas.'],[:h,'Depois da captação'],[:p,'Selecionar o material, ajustar o formato se necessário e então desenvolver os textos. As duas referências de Instagram enviadas anteriormente continuam pendentes de visualização; não foram usadas para presumir uma execução.']]
]
guide=[
  [[:tag,'Uso de produção · domingo 18/10/2026'],[:title,'Guia de captação'],[:p,'Um banco de fotos, vídeos e conversas para os conteúdos de 20 a 31/10 e os três carrosséis de favoritos. Bruna, Marcos e Suelen estarão na casa; seus itens preferidos ainda precisam ser escolhidos.'],[:h,'Antes de começar'],[:list,['Confirmar com cada um 2 ou 3 favoritos e anotar os nomes exatamente como aparecem no cardápio.','Combinar a sequência de preparo com a cozinha e separar louças, talheres e mesas.','Confirmar quem participa das fotos de experiência e da conversa sobre café.','Limpar a lente, conferir bateria e espaço; fazer um teste de imagem e áudio no local.']],[:h,'Ordem prática da visita'],[:table,[['Etapa','O que captar','Serve para'],['1 · chegada e luz','Fachada, entrada, salão, vista, mesinha vazia e cadeira para a personagem.','20 e 24/10 + banco'],['2 · pedidos e favoritos','Cada prato inteiro → detalhes → corte/gesto → retrato com quem escolheu.','22 e 29/10 + 05/11'],['3 · pessoas na casa','Pedido chegando, conversa, pausa individual e equipe orientando sobre café.','24, 27 e 31/10'],['4 · conferência','Rever nitidez, áudio e a lista dos três participantes antes de sair.','Evitar lacunas']]],[:h,'Prioridade se o tempo apertar'],[:p,'Garantir as fotos dos três favoritos com seus participantes e os planos da mesinha. Depois, chegada, pedido servido e conversa sobre café. Repetir o mínimo de montagens possível: uma mesa bem fotografada pode abastecer mais de uma pauta.'],[:p,'Não há horários rígidos neste guia: a ordem se adapta à luz e ao atendimento. A foto de cada prato deve acontecer antes do corte e da primeira garfada.']],
  [[:tag,'Lista de cenas · ambiente e experiência'],[:title,'Mostrar como é estar ali'],[:h,'Mesinha da janela · 20/10'],[:list,['Foto aberta da mesinha vazia, com as duas cadeiras, a janela e a vista.','Mesmo ângulo com pedido completo montado.','Vista de quem está sentado e detalhes de louça e luz.','Foto limpa com a cadeira inteira e espaço ao redor para inserir a Margô. Manter câmera e luz da foto principal.','Clipes de apoio: vista, pedido chegando e alguém se acomodando.']],[:h,'Manhã de domingo · 24/10'],[:list,['Vídeo da chegada pela entrada real, porta e percurso até a mesa.','Plano de mesa com luz da manhã e ambiente reconhecível ao fundo.','Pedido sendo servido, pessoa se acomodando e primeiro gesto de aproveitar a pausa.','Conversa natural ou pessoa olhando a vista; um plano mais longo de permanência.','Som de passos, louça e salão sem conversa perto do microfone.']],[:h,'Diferentes jeitos de ficar · 31/10'],[:list,['Dupla conversando: plano aberto, mãos e expressões espontâneas.','Uma pessoa em pausa individual, com café, vista ou livro se fizer parte da situação.','Mesa com pedido e pessoas no mesmo enquadramento.','Plano aberto da casa sendo vivida e detalhes que identifiquem o espaço.']],[:p,'Participantes combinados previamente. Se alguém preferir não mostrar o rosto, fotografar mãos, costas e o ponto de vista de quem está à mesa. Procurar momentos reais, sem pedir reações forçadas.']],
  [[:tag,'Lista de cenas · equipe e café'],[:title,'O acolhimento em ação'],[:h,'Conversa sobre café · 27/10'],[:list,['Escolher alguém da equipe que possa explicar como ajuda a pessoa a escolher um café.','Gravar uma conversa curta com participante: dúvida, orientação e escolha.','Registrar a explicação em um ponto menos ruidoso; ouvir o teste antes de continuar.','Captar moagem, método escolhido, café sendo servido e xícara chegando à mesa.','Fotografar a pessoa da equipe, a bebida pronta e os grãos/embalagens que ela apresentar.']],[:h,'Perguntas para conduzir a captação'],[:p,'Como vocês ajudam quem chega sem saber o que pedir? Que diferença entre duas opções vale explicar para essa pessoa? O que vocês perguntam sobre o gosto dela? São perguntas de apoio, não um roteiro para decorar.'],[:h,'Se não der para gravar a conversa'],[:p,'Registrar mãos e preparo e captar uma explicação curta em áudio separado. A decisão entre fala em cena e voz sobre as imagens fica para depois da visita.'],[:h,'Banco de apoio para todos os posts'],[:list,['Fachada, logo, entrada, mural, plantas, louças e detalhes de luz.','Mãos preparando e servindo, pedido na bandeja e chegada à mesa.','Café sendo servido e pessoa levando a xícara à boca.','Fotos verticais de planos abertos, médios e detalhes da mesma situação.']],[:h,'Padrão simples de gravação'],[:p,'Clipes verticais estáveis, em geral de 5 a 8 segundos, com sobra antes e depois da ação. Gravar em 1080 × 1920 ou 4K vertical, mantendo a mesma configuração entre cenas. Evitar zoom digital; aproximar a câmera para os detalhes. Para fala, aproximar o microfone e fazer um teste.']],
  [[:tag,'Série · captar os três episódios no domingo'],[:title,'Os favoritos de cada um'],[:p,'Bruna · proposta de publicação em 22/10 | Marcos · 29/10 | Suelen · 05/11. A ordem é sugerida e depende de aprovação.'],[:h,'Repetir esta lista para cada participante'],[:list,['Retrato vertical com o pedido: pessoa inteira no enquadramento escolhido, mãos e pratos visíveis, com espaço para o título.','Foto da combinação completa à mesa, antes de consumir.','Para cada item: foto inteiro, detalhe da textura/ingredientes visíveis e gesto de servir, cortar ou provar.','Uma foto da pessoa aproveitando sua escolha de forma natural.','Clipes extras de preparo e primeira garfada/gole, quando possível. São banco de apoio, não exigem novos Reels.','Áudio ou anotação: por que esse é um favorito e que detalhe a pessoa gostaria que o cliente percebesse.']],[:h,'Ficha rápida · preencher na visita'],[:table,[['Participante','2 ou 3 itens escolhidos','Motivos e detalhe a mostrar'],['Bruna','_____________________','_____________________'],['Marcos','_____________________','_____________________'],['Suelen','_____________________','_____________________']]],[:h,'Perguntas que rendem respostas pessoais'],[:p,'Qual seria o seu pedido aqui hoje? Por que você escolhe esse item? O que mais gosta nele? Com qual bebida combina para você? Tem alguma história ou hábito ligado a essa escolha?'],[:h,'Conferência final'],[:p,'Temos um retrato, o pedido completo, detalhes de cada item e os motivos de cada pessoa? Favoritos repetidos podem ser fotografados uma vez e ganhar retratos e relatos diferentes. Se um prato não puder sair no domingo, registrar a pendência e combinar a foto complementar.']]
]
build('Margo-calendario-aprovacao-socias-outubro-v03','Calendário para aprovação',calendar)
build('Margo-guia-captacao-domingo-18-outubro-v03','Guia de captação · 18/10',guide)
